  --error-color: #cf6679;
  --border-color: #333333;
  --focus-outline: 2px solid var(--secondary-color);
}

body {
  background-color: var(--bg-color);
  color: var(--on-bg);
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  margin: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
