#root {
  width: 100%;
  max-width: 400px;
  padding: 2rem;
}

.form-container {
  background-color: var(--surface-color);
  padding: 2rem;
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
  border: 1px solid var(--border-color);
}

