:root {
  --bg-color: #121212;
  --surface-color: #1e1e1e;
  --primary-color: #bb86fc;
  --primary-variant: #3700b3;
  --secondary-color: #03dac6;
  --on-bg: #e0e0e0;
  --on-surface: #ffffff;
  --on-primary: #000000;
  --error-color: #cf6679;
  --border-color: #333333;
  --focus-outline: 2px solid var(--secondary-color);
}

body {
  background-color: var(--bg-color);
  color: var(--on-bg);
  font-family: 'Inter', -apple-system, BlinkMacSystemFont, 'Segoe UI', Roboto, sans-serif;
  margin: 0;
  display: flex;
  justify-content: center;
  align-items: center;
  min-height: 100vh;
}

#root {
  width: 100%;
  max-width: 400px;
  padding: 2rem;
}

.form-container {
  background-color: var(--surface-color);
  padding: 2rem;
  border-radius: 12px;
  box-shadow: 0 4px 20px rgba(0, 0, 0, 0.5);
  border: 1px solid var(--border-color);
}

.form-field {
  margin-bottom: 2rem;
}

fieldset {
  border: none;
  padding: 0;
  margin: 0;
}

legend {
  font-size: 1.25rem;
  font-weight: 600;
  margin-bottom: 1rem;
  color: var(--on-surface);
}

.radio-group {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.radio-option {
  display: flex;
  align-items: center;
  cursor: pointer;
  padding: 0.75rem 1rem;
  border-radius: 8px;
  background-color: rgba(255, 255, 255, 0.05);
  transition: background-color 0.2s, border-color 0.2s;
  border: 2px solid transparent;
}

.radio-option:hover {
  background-color: rgba(255, 255, 255, 0.1);
}

.radio-option:has(input:focus-visible) {
  outline: var(--focus-outline);
  outline-offset: 2px;
}

/* Custom radio look */
input[type="radio"] {
  appearance: none;
  -webkit-appearance: none;
  width: 20px;
  height: 20px;
  border: 2px solid var(--primary-color);
  border-radius: 50%;
  margin-right: 12px;
  position: relative;
  cursor: pointer;
  outline: none;
}

input[type="radio"]:checked {
  background-color: var(--primary-color);
}

input[type="radio"]:checked::after {
  content: '';
  position: absolute;
  top: 50%;
  left: 50%;
  transform: translate(-50%, -50%);
  width: 8px;
  height: 8px;
  border-radius: 50%;
  background-color: var(--on-primary);
}

.radio-label {
  font-size: 1rem;
  color: var(--on-bg);
  cursor: pointer;
}

button[type="submit"], .btn {
  width: 100%;
  padding: 0.75rem;
  background-color: var(--primary-color);
  color: var(--on-primary);
  border: none;
  border-radius: 8px;
  font-size: 1rem;
  font-weight: 600;
  cursor: pointer;
  transition: background-color 0.2s, transform 0.1s;
  text-align: center;
  display: block;
  text-decoration: none;
}

button[type="submit"]:hover, .btn:hover {
  background-color: #a370f7;
}

button[type="submit"]:active, .btn:active {
