 const { useState } = React;

 const RadioButton = ({ id, name, value, label, checked, onChange }) => {
   return (
     <label className="radio-option" htmlFor={id}>
       <input
         type="radio"
         id={id}
         name={name}
         value={value}
         checked={checked}
         onChange={onChange}
         required
       />
       <span className="radio-label">{label}</span>
     </label>
   );
 };

 const RadioButtonGroup = ({ legend, name, options, selectedValue, onChange }) => {
   return (
     <div className="form-field">
       <fieldset>
         <legend>{legend}</legend>
         <div className="radio-group">
           {options.map((option) => (
             <RadioButton
               key={option.value}
               id={`${name}-${option.value}`}
               name={name}
               value={option.value}
               label={option.label}
               checked={selectedValue === option.value}
               onChange={(e) => onChange(e.target.value)}
             />
           ))}
         </div>
       </fieldset>
     </div>
   );
 };

 const NotificationForm = () => {
   const [preference, setPreference] = useState('');
   const [submitted, setSubmitted] = useState(false);

   const handleSubmit = (e) => {
     e.preventDefault();
     console.log('Submitted preference:', preference);
     setSubmitted(true);
     // In a real app, you might move focus to a status message here
   };

   const options = [
     { label: 'Email', value: 'email' },
     { label: 'SMS', value: 'sms' },
     { label: 'Push Notifications', value: 'push' }
   ];

   if (submitted) {
     return (
       <div className="form-container" role="status" aria-live="polite">
         <h2 style={{ marginTop: 0 }}>Preferences Saved</h2>
         <p style={{ marginBottom: '2rem' }}>You have chosen to receive notifications via <strong>{options.find(o => o.value === preference)?.label}</strong>.</p>
         <button type="button" className="btn" onClick={() => setPreference('') || setSubmitted(false)}>Change preference</button>
       </div>
     );
   }

   return (
     <div className="form-container">
       <form onSubmit={handleSubmit}>
         <RadioButtonGroup
           legend="How do you prefer to receive notifications?"
           name="notification-preference"
           options={options}
           selectedValue={preference}
           onChange={setPreference}
         />
         <button type="submit">Save Preferences</button>
       </form>
     </div>
   );
 };

 const App = () => {
   return (
     <main>
       <NotificationForm />
     </main>
   );
 };

